sql_query:
SELECT "Clinical setting"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Included in MA" = 'Yes' AND "Trial phase" = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Clinical setting" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Included in MA" = 'Yes' AND "Trial phase" = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_setting_normalized(source_value) AS "setting_normalized"
FROM base;
